module kenken_section (    input clk,    input rst_n,    input start,    input [3:0] n,    input [3:0] m,    input [31:0] t_fixed,    input [1:0] op,    input [3:0] row_addr,    input [3:0] col_addr,    input [3:0] row_data_in,    input [3:0] col_data_in,    input write_en,    output reg [31:0] count,    output reg done );    always @(posedge clk or negedge rst_n) begin        if (!rst_n) begin            count <= 32'd0;            done <= 1'b0;        end    endendmodule